#include<iostream.h>
using namespace std;
void swap(int &x, int &y)
{
int temp=x;
x=y;
y=temp;
}
int main()
{
int a=5, b=10;
swap(a,b);
swap(a,b);
cout<<a<<" "<<b;
return 0;
}
What will be the output of the above code?
(A) 5, 10
(B) 10, 5
(C) 5, 5
(D) 10, 10

